create procedure [dbo].[O7REPCZCCTR_REPCZCCTR_SUB] @sSQL ntext, @sParm nText
as
        set nocount on
        declare @nReturn int
        declare @sR5DesType             nvarchar(50)
        declare @sR5User                nvarchar(255)
        declare @sR5Org                 nvarchar(15)
        declare @sR5Func                nvarchar(6)
        declare @sR5Lang                nvarchar(2)
        declare @sSelorg                nvarchar(15)
        declare @sSelJob                nvarchar(255)
        declare @sSelmrc                nvarchar(15)
        declare @sSelProv               nvarchar(30)   
        declare @sSelServprob           nvarchar(30)   
        declare @sSelObj                nvarchar(30)
        declare @sSelLoc                nvarchar(30)
        declare @sSelprior              nvarchar(8)
        declare @sSeljobtyp             nvarchar(8)
        declare @sSelTrad               nvarchar(15)
        declare @sSelStatus             nvarchar(4)
        declare @sSelJobchild           nvarchar(1)
        declare @sSelIncmec             nvarchar(1)
        declare @sSelDtrange            nvarchar(1)
        declare @sSelBarcode            nvarchar(1)
        declare @sSelStart              nvarchar(50)
        declare @sSelEnd                nvarchar(50)
        declare @ssysdate               datetime
        declare @r5role                 nvarchar(30)


        select          @sR5DesType =  R5DesType,
                        @sR5User = R5User,
                        @sR5Org = R5Org,
                        @sR5Func = R5Func,
                        @sR5Lang = R5Lang,
                        @sSelorg = Selorg,
                        @sSelJob = SelJob,
                        @sSelmrc   = Selmrc,
                        @sSelProv  = SelProv,
                        @sSelServprob = SelServprob,
                        @sSelObj = SelObj,
                        @sSelLoc = SelLoc,
                        @sSelprior   = Selprior,
                        @sSeljobtyp  = Seljobtyp,
                        @sSelTrad = SelTrad,
                        @sSelStatus = SelStatus,
                        @sSelJobchild = SelJobchild,
                        @sSelIncmec  = SelIncmec,
                        @sSelDtrange = SelDtrange, 
                        @sSelBarcode = SelBarcode,
                        @sSelStart   = SelStart,
                        @sSelEnd     = SelEnd,
                        @ssysdate = Ssysdate,
                        @r5role = r5role
        from #tTmp

        execute sp_executesql @sSQL, @sParm, @sR5DesType, @sR5User, @sR5Org, @sR5Func, @sR5Lang, @sSelorg, @sSelJob, @sSelmrc, @sSelProv, @sSelServprob, @sSelObj, @sSelLoc, @sSelprior, @sSeljobtyp, @sSelTrad, @sSelStatus, @sSelJobchild, @sSelIncmec,  @sSelDtrange, @sSelBarcode,@sSelStart, @sSelEnd, @ssysdate, @r5role


