CREATE procedure O7REPCZCONF_REPCZCONF_SUB     @PSQL ntext,
                                               @PParm nText

as
BEGIN
    set nocount on

    declare @P_SEL_CON    nvarchar(30) 
    declare @P_SEL_SUP    nvarchar(30) 
    declare @P_SEL_STOR   nvarchar(15) 
    declare @P_SEL_ORG    nvarchar(15) 
    declare @P_R5_USER    nvarchar(255) 
    declare @P_R5_ORG     nvarchar(15) 
    declare @P_R5_DEFORG  nvarchar(15) 
    declare @P_R5_FUNC    nvarchar(6) 
    declare @P_R5_DESTYPE nvarchar(16) 
    declare @P_R5_LANG    nvarchar(2)  
    declare @P_R5ROLE     nvarchar(30)


     select @P_SEL_CON         = P_SEL_CON,
            @P_SEL_SUP         = P_SEL_SUP,
            @P_SEL_STOR        = P_SEL_STOR,
            @P_SEL_ORG         = P_SEL_ORG,
            @P_R5_USER         = P_R5_USER,
            @P_R5_ORG          = P_R5_ORG,
            @P_R5_DEFORG       = P_R5_DEFORG,
            @P_R5_FUNC         = P_R5_FUNC,
            @P_R5_DESTYPE      = P_R5_DESTYPE,
            @P_R5_LANG         = P_R5_LANG,
            @P_R5ROLE          = P_R5ROLE
     from #tCONTmp

     execute sp_executesql @PSQL, 
                           @PParm, 
                           @P_SEL_CON,      
                           @P_SEL_SUP ,    
                           @P_SEL_STOR ,   
                           @P_SEL_ORG,     
                           @P_R5_USER,     
                           @P_R5_ORG ,     
                           @P_R5_DEFORG,   
                           @P_R5_FUNC ,    
                           @P_R5_DESTYPE,  
                           @P_R5_LANG,
                           @P_R5ROLE


END


