CREATE PROCEDURE O7REPJZCODLDETAILS(  
    @R5_LANG        NVARCHAR( 2 ),
    @R5_USER        NVARCHAR( 255 ),
    @R5_ORG         NVARCHAR( 30 ),
    @PROJECT        NVARCHAR( 20 ),
    @SEL_FROM	    NVARCHAR( 20 ),
    @SEL_TO         NVARCHAR( 20 ),
    @SEL_CLASS	    NVARCHAR( 15 ) )    
AS
    SET NOCOUNT ON;

    DECLARE 
        @ent             NVARCHAR( 4 ),
        @pbccode         NVARCHAR( 20 ), 
        @budgetdesc      NVARCHAR( 255 ),
        @fromdate        DATETIME,        
        @todate          DATETIME,
        @laborcost       NUMERIC( 30,6 ),
        @stockitems      NUMERIC( 30,6 ),                                       
        @hiredlabor      NUMERIC( 30,6 ),
        @directouts      NUMERIC( 30,6 ),                                       
        @services        NUMERIC( 30,6 ),
        @toolcost        NUMERIC( 30,6 ),
        @statement       NVARCHAR( 4000 ),
        @return          INT;

    CREATE TABLE #tO7REPJZCODLRESULT ( PBC_CODE         NVARCHAR( 20 ), 
                                       BUDGET_DESC      NVARCHAR( 255 ),
                                       LABOR_COST       NUMERIC( 30,6 ),
                                       STOCK_ITEMS      NUMERIC( 30,6 ),                                       
                                       HIRED_LABOR      NUMERIC( 30,6 ),
                                       DIRECT_OUTS      NUMERIC( 30,6 ),                                       
                                       SERVICES         NUMERIC( 30,6 ),
                                       TOOL_COST        NUMERIC( 30,6 ) );

    DECLARE c_jzcodlresult CURSOR LOCAL FOR 
    SELECT 
        'PRJ' ENT,
        PBC_CODE,
        DBO.REPGETDESC( @R5_LANG, 'PBUD', PBC_CODE,NULL,NULL) BUDGET_DESC,
        CASE WHEN  @SEL_FROM='%' THEN DBO.TO_DATE('1900-01-01','YYYY-MM-DD') ELSE DBO.TO_DATE( @SEL_FROM,'YYYY-MM-DD') END FROMDATE,
        CASE WHEN @SEL_TO='%' THEN DBO.TO_DATE('2099-12-31','YYYY-MM-DD') ELSE DBO.TO_DATE(@SEL_TO,'YYYY-MM-DD') END TODATE
    FROM
        R5PROJBUDCODES, 
        R5PROJBUDCLASSES
    WHERE  
        PCL_PROJECT   =  @PROJECT AND
        PCL_PROJBUD   = PBC_CODE AND
        PCL_PROJBUD   LIKE @SEL_CLASS

    OPEN c_jzcodlresult;
    FETCH NEXT FROM c_jzcodlresult INTO @ent, @pbccode, @budgetdesc, @fromdate, @todate;

    WHILE @@FETCH_STATUS = 0
    BEGIN

        SET @laborcost = 0.0
        EXECUTE @return = o7actlab @ent, @PROJECT, @pbccode, @fromdate, @todate, @laborcost OUTPUT, @statement OUTPUT
        IF @@ERROR <> 0 OR @return <> 0
            BEGIN
              DROP TABLE #tO7REPJZCODLRESULT;
              RETURN -1;
            END;      

        SET @stockitems = 0.0
        EXECUTE @return = o7actmat @ent, @PROJECT, @pbccode, @fromdate, @todate, @stockitems OUTPUT, @statement OUTPUT
        IF @@ERROR <> 0 OR @return <> 0
            BEGIN
              DROP TABLE #tO7REPJZCODLRESULT;
              RETURN -1;
            END;    

        SET @hiredlabor = 0.0
        EXECUTE @return = o7acthir @ent, @PROJECT, @pbccode, @fromdate, @todate, @hiredlabor OUTPUT, @statement OUTPUT
        IF @@ERROR <> 0 OR @return <> 0
            BEGIN
              DROP TABLE #tO7REPJZCODLRESULT;
              RETURN -1;
            END;    

        SET @directouts = 0.0
        EXECUTE @return = o7actdma @ent, @PROJECT, @pbccode, @fromdate, @todate, @directouts OUTPUT, @statement OUTPUT
        IF @@ERROR <> 0 OR @return <> 0
            BEGIN
              DROP TABLE #tO7REPJZCODLRESULT;
              RETURN -1;
            END;    

        SET @services = 0.0
        EXECUTE @return = o7actfix @ent, @PROJECT, @pbccode, @fromdate, @todate, @services OUTPUT, @statement OUTPUT
        IF @@ERROR <> 0 OR @return <> 0
            BEGIN
              DROP TABLE #tO7REPJZCODLRESULT;
              RETURN -1;
            END;        

        SET @toolcost = 0.0
        EXECUTE @return = o7acttool @ent, @PROJECT, @pbccode, @fromdate, @todate, @toolcost OUTPUT, @statement OUTPUT
        IF @@ERROR <> 0 OR @return <> 0
            BEGIN
              DROP TABLE #tO7REPJZCODLRESULT;
              RETURN -1;
            END;       

        INSERT INTO #tO7REPJZCODLRESULT VALUES ( @pbccode, @budgetdesc, COALESCE( @laborcost, 0 ), COALESCE( @stockitems, 0 ), COALESCE( @hiredlabor, 0 ), COALESCE( @directouts, 0 ),  COALESCE( @services, 0 ), COALESCE( @toolcost, 0 ) );

        FETCH NEXT FROM c_jzcodlresult INTO @ent, @pbccode, @budgetdesc, @fromdate, @todate;
    END;
    CLOSE c_jzcodlresult;
    DEALLOCATE c_jzcodlresult;

    SELECT 
        PBC_CODE, BUDGET_DESC, 
        LABOR_COST, STOCK_ITEMS, HIRED_LABOR, DIRECT_OUTS, SERVICES, TOOL_COST,
        LABOR_COST + STOCK_ITEMS + HIRED_LABOR + DIRECT_OUTS + SERVICES + TOOL_COST TOTAL, 
        dbo.repfmtmonnumlocale( @R5_USER, @R5_ORG, LABOR_COST + STOCK_ITEMS + HIRED_LABOR + DIRECT_OUTS + SERVICES + TOOL_COST ) TOTAL_FMT,
        dbo.repfmtmonnumlocale( @R5_USER, @R5_ORG, LABOR_COST ) LABOR_FMT, 
        dbo.repfmtmonnumlocale( @R5_USER, @R5_ORG, STOCK_ITEMS ) STOCK_FMT, 
        dbo.repfmtmonnumlocale( @R5_USER, @R5_ORG, HIRED_LABOR ) HIRED_FMT, 
        dbo.repfmtmonnumlocale( @R5_USER, @R5_ORG, DIRECT_OUTS ) DIRECT_FMT, 
        dbo.repfmtmonnumlocale( @R5_USER, @R5_ORG, SERVICES ) SERVICES_FMT, 
        dbo.repfmtmonnumlocale( @R5_USER, @R5_ORG, TOOL_COST ) TOOL_FMT,
        dbo.repfmtmonnumlocale( @R5_USER, @R5_ORG, SUM( LABOR_COST ) OVER () + SUM( STOCK_ITEMS ) OVER () + SUM( HIRED_LABOR ) OVER () + SUM( DIRECT_OUTS ) OVER () + SUM( SERVICES ) OVER () + SUM( TOOL_COST ) OVER () ) SUM_TOTAL_FMT,
        dbo.repfmtmonnumlocale( @R5_USER, @R5_ORG, SUM( LABOR_COST  ) OVER () ) SUM_LABOR_FMT, 
        dbo.repfmtmonnumlocale( @R5_USER, @R5_ORG, SUM( STOCK_ITEMS ) OVER () ) SUM_STOCK_FMT, 
        dbo.repfmtmonnumlocale( @R5_USER, @R5_ORG, SUM( HIRED_LABOR ) OVER () ) SUM_HIRED_FMT, 
        dbo.repfmtmonnumlocale( @R5_USER, @R5_ORG, SUM( DIRECT_OUTS ) OVER () ) SUM_DIRECT_FMT, 
        dbo.repfmtmonnumlocale( @R5_USER, @R5_ORG, SUM( SERVICES    ) OVER () ) SUM_SERVICES_FMT, 
        dbo.repfmtmonnumlocale( @R5_USER, @R5_ORG, SUM( TOOL_COST   ) OVER () ) SUM_TOOL_FMT
    FROM #tO7REPJZCODLRESULT;

    DROP TABLE #tO7REPJZCODLRESULT;


-- ========================================

CREATE FUNCTION [dbo].[O7REPOYCPEV_CORR]
(	@CountAll		integer,
	@SumX			float,
	@SumY			float,
	@SumSQX			float,
	@SumSQY			float,
	@SumXxY			float)
	RETURNS numeric(24,12)
AS
BEGIN
	DECLARE @num	float,
			@den	float,
			@srt1	float,
			@srt2	float,
			@result numeric( 24, 12 );

	SET @result = 0;	
	SET @num =	@CountAll * @SumXxY - @SumX * @SumY;
	SET @srt1 = SQRT( @CountALL * @SumSQX - SQUARE( @SumX ));
	SET @srt2 = SQRT( @CountAll * @SumSQY - SQUARE( @SumY ));
	SET @den = @srt1 * @srt2;

	IF @den = 0
		RETURN @result;
	ELSE
		SET @result = @num / @den;

	RETURN @num / @den;

END

0

CREATE PROCEDURE [dbo].[O7REPOZRGCA_NEXTFAILURE] (
  @R5_USER NVARCHAR(255),
  @R5_ORG NVARCHAR(15),
  @R5_LANG NVARCHAR(2),
  @R5_FUNC NVARCHAR(6),
  @SEL_OBJ NVARCHAR(30),
  @SEL_ORG NVARCHAR(15),
  @SEL_TYPE NVARCHAR(5),
  @SEL_ACCO NVARCHAR(8),
  @SEL_PROB NVARCHAR(8),
  @SEL_FAIL NVARCHAR(8),
  @SEL_CAUSE NVARCHAR(8),
  @SEL_SEQ NVARCHAR(8),
  @SEL_DAY NVARCHAR(8),
  @SEL_MULTI NVARCHAR(8),
  @sCurrUser NVARCHAR( 255 ))

AS

BEGIN
  SET NOCOUNT ON;

  DECLARE @nRegressionintercept NUMERIC(30,10);
  DECLARE @nRegressionslope NUMERIC(30,10);

  DECLARE @nIecintercept  NUMERIC(30,10);
  DECLARE @nIecslope NUMERIC(30,10);

  DECLARE @nFailuresequence NUMERIC(38,0);
  DECLARE @dFailuredate DATETIME;
  DECLARE @nFailurecumulativedays NUMERIC(24,6);
  DECLARE @nFailuresequencemaxlimit NUMERIC;

  DECLARE @nRegressionnextfailurecumdays NUMERIC(24,6);
  DECLARE @nIecnextfailurecumdays NUMERIC(24,6);

  DECLARE @sRdrvapcc NVARCHAR(30);
  DECLARE @sRdrvascc NVARCHAR(30);

  DECLARE @dNextactualfailuredate DATETIME;

  declare @deptsec        nvarchar(400);

  SELECT @deptsec=INS_DESC FROM R5INSTALL WHERE INS_CODE = 'DEPTSEC'

  SET @nFailuresequencemaxlimit = 5;

  /* primary code */
  SELECT @sRdrvapcc = COALESCE( ins_desc, 'F' )
  FROM   r5install
  WHERE  ins_code = 'RDRVAPCC';

  /* secondary code */
  SELECT @sRdrvascc = COALESCE( ins_desc, 'C' )
  FROM   r5install
  WHERE  ins_code = 'RDRVASCC';

  /* for max. sequence or sequence entered */
  SELECT
    @nRegressionintercept = r1.rel_ca_intercept_cumul, 
    @nRegressionslope = r1.rel_ca_slope_cumul, 
    @nIecintercept = r1.rel_ca_intercept_iec, 
    @nIecslope = r1.rel_ca_slope_iec, 
    @nFailuresequence = r1.rel_seqno, 
    @dFailuredate = r1.rel_date, 
    @nFailurecumulativedays = r1.rel_days_cum
  FROM r5reliability r1
  WHERE
	r1.rel_object = @SEL_OBJ
    AND r1.rel_object_org = @SEL_ORG
	AND ( ( @deptsec  = N'ON' 
			AND EXISTS (SELECT 1 FROM r5departmentsecurity WHERE dse_user = @R5_USER   
					AND dse_mrc = (SELECT obj_mrc FROM r5objects WHERE obj_code = r1.rel_object AND obj_org = r1.rel_object_org ) ) )
	     OR ( @deptsec  = N'OFF'))    
	AND COALESCE( r1.rel_code1, '%' ) = CASE WHEN @sRdrvapcc = 'P' THEN @SEL_PROB
                   WHEN @sRdrvapcc = 'F' THEN @SEL_FAIL
                   WHEN @sRdrvapcc = 'C' THEN @SEL_CAUSE
                   ELSE @SEL_ACCO END
    AND COALESCE( r1.rel_code2, '%' ) = CASE WHEN @sRdrvascc = 'P' THEN @SEL_PROB
                   WHEN @sRdrvascc = 'F' THEN @SEL_FAIL
                   WHEN @sRdrvascc = 'C' THEN @SEL_CAUSE
                   ELSE @SEL_ACCO END
    AND r1.rel_seqno = CASE WHEN @SEL_SEQ = '%' THEN (SELECT MAX(rel_seqno) FROM r5reliability WHERE rel_object = r1.rel_object
                       AND rel_object_org = r1.rel_object_org AND rel_type = r1.rel_type
                       AND coalesce(rel_code1,'x') = coalesce(r1.rel_code1,'x')
                       AND coalesce(rel_code2,'x') = coalesce(r1.rel_code2,'x'))
                       ELSE CAST(@SEL_SEQ AS NUMERIC(38,0)) END
	AND (@SEL_DAY = '%' OR r1.rel_days_cum >= CAST(CASE WHEN @SEL_DAY  = '%' THEN '' ELSE @SEL_DAY  END AS NUMERIC(24,0)));

  /* return iec and regression next failure, intercept and slope */
  WITH seqno( seqno_level ) AS (
  SELECT 1 UNION ALL
  SELECT seqno_level + 1 FROM seqno WHERE seqno_level < @nFailuresequencemaxlimit )

  SELECT
    rc.seq_no SEQ_NO, 
	rc.regression_intercept REGRESSION_INTERCEPT,
	rc.regression_slope REGRESSION_SLOPE,
	rc.iec_intercept IEC_INTERCEPT,
	rc.iec_slope IEC_SLOPE,
	rc.regression_date REGRESSION_DATE,
	DBO.REPGETFMTDATELOCALE(@R5_USER, @R5_ORG, rc.regression_date) REGRESSION_DATE_FMT,
	rc.iec_date IEC_DATE,
	DBO.REPGETFMTDATELOCALE(@R5_USER, @R5_ORG, rc.iec_date) IEC_DATE_FMT,
	r.rel_date ACTUAL_DATE,
	DBO.REPGETFMTDATELOCALE(@R5_USER, @R5_ORG, r.rel_date) ACTUAL_DATE_FMT
  FROM
  (SELECT
    @nFailuresequence + (seqno_level*CAST(@SEL_MULTI AS NUMERIC)) seq_no, 
    @nRegressionintercept regression_intercept,
	@nRegressionslope regression_slope,
	@nIecintercept iec_intercept,
	@nIecslope iec_slope,
    CASE WHEN (power((@nFailuresequence + (seqno_level*CAST(@SEL_MULTI AS NUMERIC)))/@nRegressionintercept,(1/@nRegressionslope)) - @nFailurecumulativedays) <= 10950 THEN @dFailuredate + (power((@nFailuresequence + (seqno_level*CAST(@SEL_MULTI AS NUMERIC)))/@nRegressionintercept,(1/@nRegressionslope)) - @nFailurecumulativedays) ELSE NULL END regression_date,
    CASE WHEN (power((@nFailuresequence + (seqno_level*CAST(@SEL_MULTI AS NUMERIC)))/@nIecintercept,(1/@nIecslope)) - @nFailurecumulativedays) <= 10950 THEN @dFailuredate + (power((@nFailuresequence + (seqno_level*CAST(@SEL_MULTI AS NUMERIC)))/@nIecintercept,(1/@nIecslope)) - @nFailurecumulativedays) ELSE NULL END iec_date
   FROM seqno WHERE @nFailuresequence IS NOT NULL) rc
  LEFT JOIN
  (SELECT rel_seqno, rel_date
   FROM r5reliability
   WHERE 
	rel_object = @SEL_OBJ
    AND rel_object_org = @SEL_ORG
	AND ( ( @deptsec  = N'ON' 
			AND EXISTS (SELECT 1 FROM r5departmentsecurity WHERE dse_user = @R5_USER   
					AND dse_mrc = (SELECT obj_mrc FROM r5objects WHERE obj_code = rel_object AND obj_org = rel_object_org ) ) )
	     OR ( @deptsec  = N'OFF'))
    AND COALESCE( rel_code1, '%' ) = CASE WHEN @sRdrvapcc = 'P' THEN @SEL_PROB
                   WHEN @sRdrvapcc = 'F' THEN @SEL_FAIL
                   WHEN @sRdrvapcc = 'C' THEN @SEL_CAUSE
                   ELSE @SEL_ACCO END
    AND COALESCE( rel_code2, '%' ) = CASE WHEN @sRdrvascc = 'P' THEN @SEL_PROB
                   WHEN @sRdrvascc = 'F' THEN @SEL_FAIL
                   WHEN @sRdrvascc = 'C' THEN @SEL_CAUSE
                   ELSE @SEL_ACCO END) r
  ON r.rel_seqno = rc.seq_no
  WHERE @R5_USER = UPPER( COALESCE( @sCurrUser, '#' ) )
  OPTION ( MAXRECURSION 0);

END


