CREATE PROCEDURE [dbo].[O7REPOZRGCA_RESULTSET] (
  @R5_USER NVARCHAR(255),
  @R5_ORG NVARCHAR(15),
  @R5_LANG NVARCHAR(2),
  @R5_FUNC NVARCHAR(6),
  @SEL_OBJ NVARCHAR(30),
  @SEL_ORG NVARCHAR(15),
  @SEL_TYPE NVARCHAR(5),
  @SEL_ACCO NVARCHAR(8),
  @SEL_PROB NVARCHAR(8),
  @SEL_FAIL NVARCHAR(8),
  @SEL_CAUSE NVARCHAR(8),
  @SEL_SEQ NVARCHAR(8),
  @SEL_DAY NVARCHAR(8),
  @sCurrUser NVARCHAR( 255 ))

AS

BEGIN
  SET NOCOUNT ON;

  DECLARE @nRegressionintercept NUMERIC(30,10);
  DECLARE @nRegressionslope NUMERIC(30,10);
  DECLARE @nIecintercept  NUMERIC(30,10);
  DECLARE @nIecslope NUMERIC(30,10);

  DECLARE @nFailurecumulativedaysmaxlimit NUMERIC;

  DECLARE @sRdrvapcc NVARCHAR(30);
  DECLARE @sRdrvascc NVARCHAR(30);
  declare @deptsec        nvarchar(400);

  SELECT @deptsec=INS_DESC FROM R5INSTALL WHERE INS_CODE = 'DEPTSEC'

  /* primary code */
  SELECT @sRdrvapcc = COALESCE( ins_desc, 'F' )
  FROM   r5install
  WHERE  ins_code = 'RDRVAPCC';

  /* secondary code */
  SELECT @sRdrvascc = COALESCE( ins_desc, 'C' )
  FROM   r5install
  WHERE  ins_code = 'RDRVASCC';

  /* find intercept and slope values for max sequence or sequence entered*/
  SELECT
    @nRegressionintercept = r1.rel_ca_intercept_cumul, 
    @nRegressionslope = r1.rel_ca_slope_cumul, 
    @nIecintercept = r1.rel_ca_intercept_iec, 
    @nIecslope = r1.rel_ca_slope_iec, 
   @nFailurecumulativedaysmaxlimit = ROUND(r1.rel_days_cum*1.1,0)
  FROM r5reliability r1
  WHERE
    r1.rel_object = @SEL_OBJ
    AND r1.rel_object_org = @SEL_ORG
   AND ( ( @deptsec  = N'ON' 
         AND EXISTS (SELECT 1 FROM r5departmentsecurity WHERE dse_user = @R5_USER   
               AND dse_mrc = (SELECT obj_mrc FROM r5objects WHERE obj_code = r1.rel_object AND obj_org = r1.rel_object_org ) ) )
        OR ( @deptsec  = N'OFF'))
    AND COALESCE( r1.rel_code1, '%' ) = CASE WHEN @sRdrvapcc = 'P' THEN @SEL_PROB
                   WHEN @sRdrvapcc = 'F' THEN @SEL_FAIL
                   WHEN @sRdrvapcc = 'C' THEN @SEL_CAUSE
                   ELSE @SEL_ACCO END
    AND COALESCE( r1.rel_code2, '%' ) = CASE WHEN @sRdrvascc = 'P' THEN @SEL_PROB
                   WHEN @sRdrvascc = 'F' THEN @SEL_FAIL
                   WHEN @sRdrvascc = 'C' THEN @SEL_CAUSE
                   ELSE @SEL_ACCO END
    AND r1.rel_seqno = CASE WHEN @SEL_SEQ = '%' THEN (SELECT MAX(rel_seqno) FROM r5reliability WHERE rel_object = r1.rel_object
                       AND rel_object_org = r1.rel_object_org AND rel_type = r1.rel_type
                       AND coalesce(rel_code1,'x') = coalesce(r1.rel_code1,'x')
                       AND coalesce(rel_code2,'x') = coalesce(r1.rel_code2,'x'))
                       ELSE CAST(@SEL_SEQ AS NUMERIC(38,0)) END
   AND (@SEL_DAY = N'%' OR r1.rel_days_cum >= CASE WHEN @SEL_DAY <> N'%' THEN CAST(@SEL_DAY AS NUMERIC(24,0)) END);

  /* return data for scatter chart */
  WITH days( days_level ) AS (
  SELECT 1 WHERE @nFailurecumulativedaysmaxlimit IS NOT NULL
  UNION ALL
  SELECT days_level + 1 FROM days WHERE days_level < @nFailurecumulativedaysmaxlimit )

  SELECT  e.xaxis XAXIS, e.bubbletype BUBBLETYPE, e.bubblesize BUBBLESIZE, e.yaxis YAXIS, ROW_NUMBER() OVER (ORDER BY (select 1)) CATEGORY
  FROM (
    /* failure data */  
    SELECT
      rel_days_cum xaxis, 0 bubbletype, 10 bubblesize, rel_seqno yaxis
    FROM r5reliability r1
    WHERE
      r1.rel_object = @SEL_OBJ
      AND r1.rel_object_org = @SEL_ORG
     AND ( ( @deptsec  = N'ON' 
         AND EXISTS (SELECT 1 FROM r5departmentsecurity WHERE dse_user = @R5_USER   
               AND dse_mrc = (SELECT obj_mrc FROM r5objects WHERE obj_code = r1.rel_object AND obj_org = r1.rel_object_org ) ) )
        OR ( @deptsec  = N'OFF'))
      AND COALESCE( r1.rel_code1, '%' ) = CASE WHEN @sRdrvapcc = 'P' THEN @SEL_PROB
                     WHEN @sRdrvapcc = 'F' THEN @SEL_FAIL
                     WHEN @sRdrvapcc = 'C' THEN @SEL_CAUSE
                     ELSE @SEL_ACCO END
      AND COALESCE( r1.rel_code2, '%' ) = CASE WHEN @sRdrvascc = 'P' THEN @SEL_PROB
                     WHEN @sRdrvascc = 'F' THEN @SEL_FAIL
                     WHEN @sRdrvascc = 'C' THEN @SEL_CAUSE
                     ELSE @SEL_ACCO END
      AND (@SEL_SEQ = N'%' OR r1.rel_seqno <= CASE WHEN @SEL_SEQ <> N'%' THEN CAST(@SEL_SEQ AS NUMERIC(38,0)) END )
      AND (@SEL_DAY = N'%' OR r1.rel_days_cum >= CASE WHEN @SEL_DAY <> N'%' THEN CAST(@SEL_DAY AS NUMERIC(24,0)) END) 

    UNION ALL
   /* regression data */
    SELECT
      days_level xaxis, 1 bubbletype, 3 bubblesize, @nRegressionintercept*power(cast(days_level as float),@nRegressionslope)  yaxis                      
    FROM days
    WHERE
      (@SEL_DAY = N'%' OR days_level >= CASE WHEN @SEL_DAY <> N'%' THEN CAST(@SEL_DAY AS NUMERIC(24,0)) END)
     AND @SEL_TYPE IN ('B','R')

    UNION ALL
   /* iec data */
    SELECT
      days_level xaxis, 2 bubbletype, 3 bubblesize, @nIecintercept*power(cast(days_level as float),@nIecslope) yaxis                      
    FROM days
    WHERE
     (@SEL_DAY = N'%' OR days_level >= CASE WHEN @SEL_DAY <> N'%' THEN CAST(@SEL_DAY AS NUMERIC(24,0)) END)
     AND @SEL_TYPE IN ('B','I')
  ) E
  WHERE @R5_USER = UPPER( COALESCE( @sCurrUser, '#' ) )
  OPTION ( MAXRECURSION 0);

END


