CREATE PROCEDURE O7REPOZRHIS_PERIOD(  
        @r5user        NVARCHAR( 255 ),
        @r5org         NVARCHAR( 15 ),
        @r5lang        NVARCHAR( 2 ),
        @r5function    NVARCHAR( 6 ),
        @selobj        NVARCHAR( 30 ),
        @selorg        NVARCHAR( 15 ),
        @selstart      NVARCHAR( 50 ),
        @selend        NVARCHAR( 50 ),
        @selcbci       NVARCHAR( 51 ),
        @selcbrpi      NVARCHAR( 51 ),
        @selcbcri      NVARCHAR( 51 ),
        @curruser      NVARCHAR( 255 ),
        @r5role        NVARCHAR( 30 ) )
AS
    SET NOCOUNT ON;

    DECLARE 
        @yearlyaverageusage NUMERIC( 24, 6 ),
        @servicelife        NUMERIC( 3, 0 ),
        @servicelifeusage   NUMERIC( 24, 6 ),
        @commissiondate     DATETIME,
        @primaryuom         NVARCHAR( 30 ),
        @deptsec            NVARCHAR( 30 ),
        @tempobj            NVARCHAR( 30 ),
        @tempobjorg         NVARCHAR( 15 ),
        @xaxisformat        NVARCHAR( 4000 ),
        @xaxis              DATETIME,
        @conditionline      NUMERIC( 24, 6 ), 
        @thresholdline      NUMERIC( 24, 6 ),
        @decaycurveline     NUMERIC( 24, 6 ), 
        @riskpriorityline   NUMERIC( 24, 6 ), 
        @criticalityline    NUMERIC( 24, 6 ),
        @corrconditionscore NUMERIC( 24, 6 ),
        @corrconditiondate  DATETIME,
        @equipment          NVARCHAR( 30 )   = '#',
        @equipmentorg       NVARCHAR( 15 )   = '#',
        @agecorrection      NUMERIC( 24, 6 ) = 0,      
        @return             INT;

    /* deptsec code */
    SELECT @deptsec = UPPER( COALESCE( ins_desc, 'OFF' ) )
    FROM   r5install
    WHERE  ins_code = 'DEPTSEC';

    /* Get Yearly Average Usage, Service Life, Service Life Usage */
    SELECT 
      @yearlyaverageusage = 
      COALESCE(  ( SELECT COALESCE ( oud_calcdailyusg, oud_dfltdailyusg ) * 365 
                                FROM r5objusagedefs 
                                WHERE oud_object = o.obj_code
                                      AND oud_object_org = o.obj_org
                                      AND oud_uom = o.obj_primaryuom ) , 
                  ( SELECT ( ( erh_usage * 1.0 ) / CASE WHEN DATEDIFF( DAY, erh_date, o.obj_commiss ) <= 0 THEN 1 ELSE DATEDIFF( DAY, erh_date, o.obj_commiss ) END ) * 365 
                    FROM r5equipmentrankinghistory 
                    WHERE erh_primaryuom = o.obj_primaryuom
                          AND erh_rankingtype = 'CI'
                          AND erh_objcode = o.obj_code
                          AND erh_objorg = o.obj_org
                          AND erh_date = ( SELECT MAX( erh_date ) FROM r5equipmentrankinghistory e2
                                           WHERE e2.erh_primaryuom = erh_primaryuom
                                                 AND e2.erh_rankingtype = erh_rankingtype
                                                 AND e2.erh_objcode = erh_objcode
                                                 AND e2.erh_objorg = erh_objorg ) ) ),
      @servicelife =                                            
      COALESCE( ( SELECT erh_servicelife 
                    FROM r5equipmentrankinghistory 
                    WHERE erh_rankingtype = 'CI'
                          AND erh_objcode = o.obj_code
                          AND erh_objorg = o.obj_org
                          AND erh_servicelife IS NOT NULL
                          AND erh_date = ( SELECT MAX( erh_date ) FROM r5equipmentrankinghistory e2
                                           WHERE e2.erh_primaryuom = erh_primaryuom
                                                 AND e2.erh_rankingtype = erh_rankingtype
                                                 AND e2.erh_objcode = erh_objcode
                                                 AND e2.erh_objorg = erh_objorg ) ),
                o.obj_servicelife,
                (  SELECT ocd_servicelife FROM r5assetclassdefinition WHERE ocd_category = o.obj_category ),
                (  SELECT ocd_servicelife FROM r5assetclassdefinition WHERE ocd_class = o.obj_class AND ocd_class_org = o.obj_class_org AND ocd_category IS NULL ) ),
      @servicelifeusage = 
      COALESCE( ( SELECT erh_servicelifeusage 
                    FROM r5equipmentrankinghistory 
                    WHERE erh_rankingtype = 'CI'
                          AND erh_objcode = o.obj_code
                          AND erh_objorg = o.obj_org
                          AND erh_servicelifeusage IS NOT NULL
                          AND erh_date = ( SELECT MAX( erh_date ) FROM r5equipmentrankinghistory e2
                                           WHERE e2.erh_primaryuom = erh_primaryuom
                                                 AND e2.erh_rankingtype = erh_rankingtype
                                                 AND e2.erh_objcode = erh_objcode
                                                 AND e2.erh_objorg = erh_objorg ) ),
                o.obj_servicelifeusage,
                ( SELECT ocd_servicelifeusage FROM r5assetclassdefinition WHERE ocd_category = o.obj_category ),
                ( SELECT ocd_servicelifeusage FROM r5assetclassdefinition WHERE ocd_class = o.obj_class AND ocd_class_org = o.obj_class_org AND ocd_category IS NULL ) ),
      @commissiondate = o.obj_commiss,
      @primaryuom = COALESCE( o.obj_primaryuom, '#' ),
      @corrconditionscore = o.obj_corrconditionscore,
      @corrconditiondate = o.obj_corrconditiondate,
      @equipment = o.obj_code,
      @equipmentorg = o.obj_org        
    FROM r5objects o
    WHERE 
      o.obj_code    = @selobj
      AND o.obj_org = @selorg
      AND EXISTS (    SELECT 'X' 
                      FROM 
                          r5userorganization u
                      WHERE 
                          u.uog_org = o.obj_org
                          AND u.uog_user = @r5user
                          AND u.uog_role = @r5role )
      AND ( ( @deptsec  = 'ON' 
                  AND EXISTS ( SELECT 1 FROM r5departmentsecurity WHERE dse_user = @r5user AND dse_mrc = o.obj_mrc ) ) 
            OR ( @deptsec  = 'OFF' ) )
      AND @r5user = UPPER( COALESCE( @curruser, '#' ) );

      /* Get x-axis age correction for decaycurveline */  
      SELECT 
        @agecorrection  = 
          CASE 
              WHEN c.dcr_xaxis_uom_type = 'P' AND c.dcr_perioduom = 'Y' AND @commissiondate IS NOT NULL
                   THEN ( DATEDIFF( dd, @commissiondate, @corrconditiondate ) / 365.0 ) - c.referencepoint
              WHEN c.dcr_xaxis_uom_type = 'U' AND @yearlyaverageusage > 0 AND c.dcr_metuom = @primaryuom AND @commissiondate IS NOT NULL
                   THEN ( DATEDIFF( dd, @commissiondate, @corrconditiondate ) / 365.0 ) - c.referencepoint/@yearlyaverageusage
              WHEN dcr_xaxis_uom_type = 'C' AND @servicelife IS NOT NULL AND @commissiondate IS NOT NULL
                   THEN ( DATEDIFF( dd, @commissiondate, @corrconditiondate ) / 365.0 ) - ( c.referencepoint/100.0 * @servicelife )
          END
      FROM                   
        ( SELECT TOP 1 dcr_xaxis_uom_type, dcr_perioduom, dcr_metuom, cpd_periodusage AS referencepoint
          FROM 
            r5equipmentrankings 
            INNER JOIN r5reliabilityrankings ON eqr_rankingcode = rrk_code AND eqr_rankingorg = rrk_org AND eqr_rankingrevision = rrk_revision
            INNER JOIN r5decaycurve ON dcr_code = rrk_decaycurve AND dcr_org = rrk_decaycurve_org 
            INNER JOIN r5decaycurvepoints ON dcr_code = cpd_dccode AND dcr_org = cpd_dcorg
          WHERE
            rrk_rtype       = 'CI'
            AND eqr_objcode = @equipment
            AND eqr_objorg  = @equipmentorg
            AND @selcbci     = '+'
            AND @corrconditionscore IS NOT NULL 
            AND @corrconditiondate <= GETDATE()
          ORDER BY ABS ( cpd_conditionscore - @corrconditionscore ) ) C;


    CREATE TABLE #


