CREATE FUNCTION O7REPSUBOLLITAGS(
  @stringin NVARCHAR(MAX) ) RETURNS NVARCHAR(MAX) AS
 BEGIN
	DECLARE @olstartpos        NUMERIC;
	DECLARE @olendpos        NUMERIC;
	DECLARE @lino     NUMERIC = 1;
	DECLARE @wholestr   NVARCHAR(MAX);
	DECLARE @finalstr NVARCHAR(MAX);
	DECLARE @firstol NVARCHAR(MAX);
	DECLARE @remainingol NVARCHAR(MAX);
	DECLARE @nonolseg NVARCHAR(MAX);
	DECLARE @olseg NVARCHAR(MAX);

	SET @wholestr = @stringin;
	-- return if ol end tags not found
	IF CHARINDEX( N'</ol>', LOWER(@wholestr)) = 0
	BEGIN
	RETURN( @wholestr );
	END 

	SET @olendpos = COALESCE(CHARINDEX( N'</ol>', LOWER(@wholestr)),0);
	WHILE @olendpos > 0
	BEGIN
		-- split whole string
		SET @firstol = SUBSTRING(@wholestr, 1, @olendpos + 4);
		SET @remainingol = SUBSTRING(@wholestr,@olendpos + 5, LEN(@wholestr));

		-- find non-ol and ol part string segments
		SET @olstartpos = COALESCE(CHARINDEX( N'<ol', LOWER(@firstol)),0);
		SET @nonolseg = SUBSTRING(@firstol, 1, @olstartpos - 1);
		SET @olseg = SUBSTRING(@firstol, @olstartpos , LEN(@firstol));

		-- save non-ol part into final string
		SET @finalstr = COALESCE(@finalstr,N'') + COALESCE(@nonolseg,N'');

		-- process ol part segment for li tags
		WHILE COALESCE(CHARINDEX(N'<li', LOWER(@olseg)),0) > 0
		BEGIN
			-- replace li start tag with no
			SET @olseg = STUFF(@olseg,
                            CHARINDEX(N'<li',@olseg),
                            CHARINDEX(N'>',@olseg, CHARINDEX(N'<li',@olseg))-CHARINDEX(N'<li',@olseg)+1,
                            CHAR(10) + CAST(@lino AS NVARCHAR) + N'. ')
			SET @lino = @lino + 1;
		END;

		-- save into final string
		SET @finalstr = COALESCE(@finalstr,N'') + @olseg;

		-- initialize again
		SET @wholestr = @remainingol;
		SET @olendpos = COALESCE(CHARINDEX(N'</ol>', LOWER(@wholestr)),0);
		SET @lino = 1;
	END;

	-- save remaining string  
	SET @finalstr = COALESCE(@finalstr,N'') + COALESCE(@remainingol,N'');

	RETURN (@finalstr);
END
