CREATE PROCEDURE O7REPWZPSCRDETAILS(  
    @R5_USER        NVARCHAR( 255 ),
    @R5_FUNC        NVARCHAR( 6 ),
    @SEL_PROJ       NVARCHAR( 20 ),
    @SEL_ORG	      NVARCHAR( 15 ),
    @CURRUSER       NVARCHAR( 255 ),
    @r5role         NVARCHAR( 30 ) )
AS
    SET NOCOUNT ON;

    DECLARE 
        @ent                NVARCHAR( 4 ),
        @project            NVARCHAR( 20 ),
        @projorg            NVARCHAR( 15 ),
        @pbccode            NVARCHAR( 20 ), 
        @currentbudget      NUMERIC( 30,6 ),
        @budgetapproved     NUMERIC( 30,6 ), 
        @fromdate           DATETIME,        
        @todate             DATETIME,        
        @actualcosttodate   NUMERIC( 30,6 ),
        @laborcost          NUMERIC( 30,6 ),
        @stockitems         NUMERIC( 30,6 ),                                       
        @hiredlabor         NUMERIC( 30,6 ),
        @directouts         NUMERIC( 30,6 ),                                       
        @services           NUMERIC( 30,6 ),
        @toolcost           NUMERIC( 30,6 ),
        @statement          NVARCHAR( 4000 ),
        @return             INT;

    CREATE TABLE #tO7REPWZPSCRRESULT ( Project             NVARCHAR( 20 ), 
                                       Organization        NVARCHAR( 15 ),
                                       CurrentBudget       NUMERIC( 30,6 ),
                                       BudgetApproved      NUMERIC( 30,6 ),                                       
                                       ActualCostToDate    NUMERIC( 30,6 ) );

    DECLARE c_wzpscrresult CURSOR LOCAL FOR 
    SELECT  
        'PRJ' ENT,
        P.PRJ_CODE,
        P.PRJ_ORG,
        PBC.PBC_CODE, 
        P.PRJ_ACTBUD,  
        P.PRJ_ORIGBUD
    FROM   	
        R5PROJECTS P, 
        R5PROJBUDCODES PBC,
        R5PROJBUDCLASSES PCL
    WHERE  	
        (@SEL_ORG   = '%' OR P.PRJ_ORG LIKE @SEL_ORG) 
        AND    	P.PRJ_CODE = @SEL_PROJ
        AND    	PCL.PCL_PROJECT = P.PRJ_CODE 
        AND    	PCL.PCL_PROJBUD = PBC.PBC_CODE
        AND     @R5_USER = UPPER( COALESCE( @CURRUSER, '#' ) )
        AND 	P.PRJ_ORG  IN    (SELECT UOG_ORG FROM R5USERORGANIZATION,R5PERMISSIONS 
                                            WHERE UOG_GROUP= PRM_GROUP AND 
                                            PRM_SELECT='?' AND 
                                            UOG_USER = @R5_USER AND 
                                            UOG_ROLE = @r5role AND 
                                            PRM_FUNCTION = @R5_FUNC );

    SET @fromdate = DBO.TO_DATE('1900-01-01','YYYY-MM-DD');
    SET @todate = DBO.TO_DATE('2099-12-31','YYYY-MM-DD');

    OPEN c_wzpscrresult;
    FETCH NEXT FROM c_wzpscrresult INTO @ent, @project, @projorg, @pbccode, @currentbudget, @budgetapproved;

    WHILE @@FETCH_STATUS = 0
    BEGIN

        SET @laborcost = 0.0
        EXECUTE @return = o7actlab @ent, @SEL_PROJ, @pbccode, @fromdate, @todate, @laborcost OUTPUT, @statement OUTPUT
        IF @@ERROR <> 0 OR @return <> 0
            BEGIN
              DROP TABLE #tO7REPWZPSCRRESULT;
              RETURN -1;
            END;      

        SET @stockitems = 0.0
        EXECUTE @return = o7actmat @ent, @SEL_PROJ, @pbccode, @fromdate, @todate, @stockitems OUTPUT, @statement OUTPUT
        IF @@ERROR <> 0 OR @return <> 0
            BEGIN
              DROP TABLE #tO7REPWZPSCRRESULT;
              RETURN -1;
            END;    

        SET @hiredlabor = 0.0
        EXECUTE @return = o7acthir @ent, @SEL_PROJ, @pbccode, @fromdate, @todate, @hiredlabor OUTPUT, @statement OUTPUT
        IF @@ERROR <> 0 OR @return <> 0
            BEGIN
              DROP TABLE #tO7REPWZPSCRRESULT;
              RETURN -1;
            END;    

        SET @directouts = 0.0
        EXECUTE @return = o7actdma @ent, @SEL_PROJ, @pbccode, @fromdate, @todate, @directouts OUTPUT, @statement OUTPUT
        IF @@ERROR <> 0 OR @return <> 0
            BEGIN
              DROP TABLE #tO7REPWZPSCRRESULT;
              RETURN -1;
            END;    

        SET @services = 0.0
        EXECUTE @return = o7actfix @ent, @SEL_PROJ, @pbccode, @fromdate, @todate, @services OUTPUT, @statement OUTPUT
        IF @@ERROR <> 0 OR @return <> 0
            BEGIN
              DROP TABLE #tO7REPWZPSCRRESULT;
              RETURN -1;
            END;        

        SET @toolcost = 0.0
        EXECUTE @return = o7acttool @ent, @SEL_PROJ, @pbccode, @fromdate, @todate, @toolcost OUTPUT, @statement OUTPUT
        IF @@ERROR <> 0 OR @return <> 0
            BEGIN
              DROP TABLE #tO7REPWZPSCRRESULT;
              RETURN -1;
            END;       

        INSERT INTO #tO7REPWZPSCRRESULT VALUES ( @project, @projorg, @currentbudget, @budgetapproved, COALESCE( @laborcost, 0 ) + COALESCE( @stockitems, 0 ) + COALESCE( @hiredlabor, 0 ) + COALESCE( @directouts, 0 ) +  COALESCE( @services, 0 ) + COALESCE( @toolcost, 0 ) );

        FETCH NEXT FROM c_wzpscrresult INTO @ent, @project, @projorg, @pbccode, @currentbudget, @budgetapproved;
    END;
    CLOSE c_wzpscrresult;
    DEALLOCATE c_wzpscrresult;

    SELECT Project, Organization, MIN ( CurrentBudget ) "Current Budget", MIN ( BudgetApproved ) "Budget Approved",  SUM( ActualCostToDate ) "Actual Cost To-Date"  FROM #tO7REPWZPSCRRESULT GROUP BY Project, Organization ;

    DROP TABLE #tO7REPWZPSCRRESULT;


