create PROCEDURE  O7SCHTOOL @sSource    nvarchar(3),
                   @sEvtCode  nvarchar(30),
                   @sActCode  nvarchar(8),
                   @dOldDate  datetime,
                   @dNewDate  datetime,
                   @sCheckresult nvarchar(4) OUTPUT 
AS
	SET NOCOUNT ON
	declare @dDatedif    numeric(24,8)

	set @sCheckresult = '0'
	set @dDatedif     = cast(@dNewDate - @dOldDate as numeric(24,8))
	if( @dDatedif <> 0 ) 
	begin
		if( @sSource = N'EVT' ) 
			UPDATE r5toolreq
			SET tor_required = tor_required + @dDatedif
			WHERE tor_event = @sEvtCode

		if( @sSource = N'ACT' ) 
			UPDATE r5toolreq
			SET tor_required = tor_required + @dDatedif
			WHERE tor_event = @sEvtCode
			AND tor_act = @sActCode
	end


