create procedure O7UPBIS1	@sStore		nvarchar(15),
							@sPart		nvarchar(30),
							@sPartOrg		nvarchar(15),
							@nQuantity	numeric(24,6),
							@nRepairQty	numeric(24,6),
							@sChkresult	nvarchar(8)	OUTPUT
as
	SET NOCOUNT ON

	set @sChkresult	= N'0'

	UPDATE r5stock 
	SET    sto_qty       = Coalesce( sto_qty, 0 )       - Coalesce( @nQuantity, 0 ),
		   sto_repairqty = Coalesce( sto_repairqty, 0 ) - Coalesce( @nRepairQty, 0 )
	WHERE  sto_store    = @sStore
	AND    sto_part     = @sPart
	AND    sto_part_org = @sPartOrg


