create procedure O7UPINV1_CREATE_TRANS(	
  @sTraorg     nvarchar( 15 ), 
  @sTrastore   nvarchar( 15 ), 
  @sTradesc    nvarchar( 80 ), 
  @sUser       nvarchar( 255 ), 
  @sTrlpart    nvarchar( 30 ),
  @sTrlpartorg nvarchar( 15 ),
  @nQty        numeric( 24, 6 ),
  @nPrice      numeric( 24, 6 ),
  @sOrder      nvarchar(30),
  @sOrderorg   nvarchar(15),
  @nOrdline    numeric(8))
as
begin
  declare   @sCheckresult   nvarchar( 4 )
  declare   @sRtype         nvarchar( 4 )
  declare   @sUtype         nvarchar( 4 )
  declare   @sTracode       nvarchar( 30 )
  declare   @nReturn        int

  set @sRtype = N'INVC'

  /* Get next transaction number. */
  execute @nReturn = R5O7_O7MAXSEQ @sTracode OUTPUT, N'TRAN', N'1', @sCheckresult OUTPUT

  /* Insert transaction header. */
  insert into r5transactions( tra_code, tra_org, tra_desc, tra_auth, tra_rtype,
         tra_date, tra_fromcode, tra_fromrentity, tra_fromrtype, tra_rstatus, tra_printed, tra_order, tra_order_org )
  values( @sTracode, @sTraorg, @sTradesc, @sUser, @sRtype,
          dbo.F_TRUNC_DATE( dbo.o7gttime2( @sTraorg ), N'DD' ) , @sTrastore, N'STOR', N'*', N'A', N'-', @sOrder, @sOrderorg )

  /* Get utype. */
  execute @nReturn = r5o7_o7ucode @sUtype OUTPUT, @sRtype, N'TRTP', @sCheckresult OUTPUT

  /* Insert transaction line. */
  insert into r5translines( trl_part, trl_part_org, trl_store, trl_line, trl_type, 
         trl_rtype, trl_trans, trl_date, trl_qty, trl_price, trl_io, trl_order, trl_order_org, trl_ordline )
  values( @sTrlpart, @sTrlpartorg, @sTrastore, 1, @sUtype, 
          @sRtype, @sTracode, dbo.F_TRUNC_DATE( dbo.o7gttime2( @sTraorg ), N'DD' ), @nQty, @nPrice, 1, @sOrder, @sOrderorg,@nOrdline );

end


