CREATE PROCEDURE O7VPOAPR 
						   @sCdockid        nvarchar(30),
						   @sClineNum       numeric(8,0)  OUTPUT,
						   @sChk            nvarchar(5)   OUTPUT,
						   @sDockLineid     int
AS
	SET NOCOUNT ON
	declare @sVauto          nvarchar(200)	--r5install.ins_desc%TYPE
    declare @sCheckResult    nvarchar(4) 	--= '0'
    declare @nN_total        int
    declare @sVorderLineType nvarchar(4)	--r5orderlines.orl_rtype%TYPE
	declare @nReturn int

	declare @sDkl_dckcode	nvarchar(30),
	        @nDkl_line		numeric(8,0),
	     	@sDkl_bin		nvarchar(15),
	     	@sDkl_part		nvarchar(30),
	     	@sDdkl_direct	nvarchar(1),
	     	@nDkl_countqty	numeric(24,6),
	     	@sDkl_order		nvarchar(30),
            @sDkl_order_org	nvarchar(15),
	     	@nDkl_ordline	numeric(8,0),
	     	@sDkl_part_org	nvarchar(15),
	     	@sPar_byasset 	nvarchar(1),
	     	@sDkl_object	nvarchar(30)

	set @sClineNum = 0
	set @nN_total = 0
    -- check to see if need to auto generate asset number
	execute @nReturn = O7DFLT @sVauto OUTPUT, N'AUTOANUM', @sCheckResult OUTPUT
	if @@ERROR <> 0 or @nReturn <> 0
		return -1
    IF @sCheckResult <> 0
        set @sVauto = N'NO'
	declare cCursor_dockline cursor local for
	    SELECT d.dkl_dckcode,
	           d.dkl_line,
	     	   d.dkl_bin,
	     	   d.dkl_part,
	     	   d.dkl_direct,
	     	   d.dkl_countqty,
	     	   d.dkl_order,
               d.dkl_order_org,
	     	   d.dkl_ordline,
	     	   d.dkl_part_org,
	     	   p.par_byasset dkl_byasset,
	     	   d.dkl_object
	     	   FROM   r5docklines d, r5parts p
	     	   WHERE  d.dkl_dckcode     = @sCdockid
	     	   AND    ( d.dkl_linerstatus = N'R' OR d.dkl_linerstatus = N'U' )
	     	   AND    d.dkl_part        = p.par_code
	     	   AND    d.dkl_part_org    = p.par_org
	     	   AND    d.dkl_line        = case when @sDockLineid = -1 then d.dkl_line else @sDockLineid end
	open cCursor_dockline
	fetch next from cCursor_dockline into   @sDkl_dckcode,
									        @nDkl_line,
									     	@sDkl_bin,
									     	@sDkl_part,
									     	@sDdkl_direct,
									     	@nDkl_countqty,
									     	@sDkl_order,
                                            @sDkl_order_org,
									     	@nDkl_ordline,
									     	@sDkl_part_org,
									     	@sPar_byasset,
									     	@sDkl_object
	while @@fetch_status = 0
	begin
    	-- processing docklines
        set @nN_total = @nN_total + 1

		SELECT @sVorderLineType = orl_rtype
		FROM   r5orderlines
		WHERE  orl_order = @sDkl_order
		AND    orl_order_org = @sDkl_order_org
		AND    orl_ordline = @nDkl_ordline

        -- check count quantity
        IF isnull(@nDkl_countqty, 0 ) <= 0
            begin
                IF (@sVorderLineType <> N'RE') 
                    begin
       	                set @sClineNum = @nDkl_line
                        break
                    end
		    end

		-- check if the bin is there
        IF (@sDkl_bin IS NULL )
		    begin
       		    IF (@sVorderLineType <> N'PD' )
			    begin
         		    set @sClineNum = @nDkl_line
         		    break
       		    end
     	    end

        -- check if asset id exists
        IF ((@sPar_byasset = N'+') AND (UPPER( @sVauto ) <> N'YES') AND (@sDkl_object IS NULL) )
            begin	
			    set @sClineNum = @nDkl_line
        	    break
            end

		fetch next from cCursor_dockline into   @sDkl_dckcode,
										        @nDkl_line,
										     	@sDkl_bin,
										     	@sDkl_part,
										     	@sDdkl_direct,
										     	@nDkl_countqty,
										     	@sDkl_order,
										     	@sDkl_order_org,
										     	@nDkl_ordline,
										     	@sDkl_part_org,
										     	@sPar_byasset,
										     	@sDkl_object
	end 
	close cCursor_dockline
	deallocate cCursor_dockline
	IF (@nN_total = 0)
        set @sChk = N'1'


