create procedure O7WDACTJ_POSTQUERY 
			@sPAct_act			nvarchar(8),
			@sPAct_event		nvarchar(30),
			@sPAct_order		nvarchar(30),
			@sPAct_order_org	nvarchar(15),
			@sPAct_ordline		nvarchar(8),
			@sPAct_task			nvarchar(20),
			@sPAct_taskrev		nvarchar(4),
			@sPOrlcurr			nvarchar(3) OUTPUT,
			@nPOrlexch			numeric(24,6) OUTPUT,
			@nPOrlprice			numeric(24,6) OUTPUT,
			@nPTsk_hours		numeric(24,6) OUTPUT,
			@sPAct_tool			nvarchar(1) OUTPUT
AS 
SET NOCOUNT ON

begin



	if @sPAct_order IS NOT NULL 
		begin
			SELECT	@nPOrlprice = orl_price,
					@sPOrlcurr = orl_curr,
					@nPOrlexch = orl_exch
			FROM   r5orderlines
			WHERE  orl_order_org   = @sPAct_order_org
			AND    orl_order       = @sPAct_order
			AND    orl_ordline     = @sPAct_ordline
		end

	if @sPAct_task IS NOT NULL 
		begin
			SELECT @nPTsk_hours = tsk_hours
			FROM   r5tasks
			WHERE  tsk_code     = @sPAct_task
			AND    tsk_revision = @sPAct_taskrev
		end



	Select 1 FROM r5toolreq
	WHERE tor_event = @sPAct_event
	AND tor_act     = @sPAct_act

	If @@ROWCOUNT > 0 
		set @sPAct_tool = N'+'
	else
		set @sPAct_tool = N'-'

end


