CREATE PROCEDURE O7WEIBULL
  @nShape    NUMERIC( 20, 10 ) OUTPUT,
  @nScale    NUMERIC( 20, 10 ) OUTPUT,
  @nCorr     NUMERIC( 20, 10 ) OUTPUT,
  @nLaplace  NUMERIC( 20, 10 ) OUTPUT 
AS
BEGIN
  DECLARE @nRecs       NUMERIC             -- The number of records in table r5weibull
  DECLARE @nAvgx       NUMERIC( 20, 10 )   -- The average of column wei_x
  DECLARE @nAvgy       NUMERIC( 20, 10 )   -- The average of column wei_y
  DECLARE @nSumvalue   NUMERIC( 20, 10 )   -- The sum of column wei_value, only used for laplace
  DECLARE @nSumvalue2  NUMERIC( 20, 10 )   -- The weighted sum of column wei_value, only used for laplace
  DECLARE @nSumxy      NUMERIC( 20, 10 )   -- Sum of difference from average for X * Sum of difference from average for Y
  DECLARE @nSumxx      NUMERIC( 20, 10 )   -- Sum of difference from average for X * Sum of difference from average for X
  DECLARE @nSumyy      NUMERIC( 20, 10 )   -- Sum of difference from average for Y * Sum of difference from average for Y
  DECLARE @nSlope      NUMERIC( 20, 10 )   -- Dummy variable to prevent division by 0.
  DECLARE @nReturn     INT

  /* Retrieve the total number of records used in the calculations. */
  SELECT @nRecs = COUNT(*)
  FROM   #tweibull

  /* Give columns wei_x and wei_y a value, using Weibull specific formulas. */
  UPDATE #tweibull
  SET    wei_x = LOG( LOG( 1 / ( 1 - ( ( wei_rank - 0.3 ) / ( @nRecs + 0.4 ) ) ) ) ),
         wei_y = LOG( wei_value )

  /* Calculate some intermediate values, used in the calculation of the Weibull correlation and Laplace. */
  SELECT @nAvgx      = AVG( wei_x ),
         @nAvgy      = AVG( wei_y ),
         @nSumvalue  = SUM( wei_value ),
         @nSumvalue2 = SUM( wei_value * ( @nRecs - wei_seqno ) )
  FROM   #tweibull

  /* Calculate some more intermediate values, used in the calculation of the Weibull correlation. */
  SELECT @nSumxy = SUM( ( wei_x - @nAvgx ) * ( wei_y - @nAvgy ) ),
         @nSumxx = SUM( ( wei_x - @nAvgx ) * ( wei_x - @nAvgx ) ),
         @nSumyy = SUM( ( wei_y - @nAvgy ) * ( wei_y - @nAvgy ) )
  FROM   #tweibull

  /* Calculate the Weibull shape. */
  EXECUTE @nReturn = o7getslope '#tweibull', 'wei_y', 'wei_x', NULL, '', @nSlope OUTPUT
  IF @nSlope = 0
    /* Prevent division by 0, set shape to NULL. */
    SET @nShape = NULL
  ELSE
    SET @nShape = 1 / @nSlope

  /* Calculate the Weibull scale. */
  SET @nScale = POWER( 2.71828183, @nAvgy - ( @nAvgx / @nShape ) )

  /* Calculate the Weibull correlation. */
  IF SQRT( @nSumxx * @nSumyy ) <> 0 
    SET @nCorr = @nSumxy / SQRT( @nSumxx * @nSumyy )

  /* Calculate Laplace. */
  SET @nLaplace = ( ( @nSumvalue2 / ( @nRecs - 1 ) ) - ( @nSumvalue / 2 ) ) /
                    ( @nSumvalue * SQRT( ( 1 / ( 12 * ( @nRecs - 1 ) ) ) ) )

END


