         @objobtype       = n.obj_obtype, 
         @objobrtype      = n.obj_obrtype, 
         @objcostcode     = n.obj_costcode,
         @objparent       = n.obj_parent, 
         @objposition     = n.obj_position,
         @objsyslevel     = o.obj_syslevel, 
         @objasmlevel     = o.obj_asmlevel, 
         @objcomplevel    = o.obj_complevel, 
         @objcomplocation = o.obj_complocation, 
         @oldpart         = o.obj_part, 
         @oldpartorg      = o.obj_part_org,
         @oldobtype       = o.obj_obtype, 
         @oldobrtype      = o.obj_obrtype, 
         @oldcostcode     = o.obj_costcode, 
         @oldlot          = o.obj_lot, 
         @oldrstatus      = o.obj_rstatus,
         @oldstatus       = o.obj_status 
  FROM   r5users, r5objects n, r5objects o 
         LEFT OUTER JOIN r5parts ON ( par_code = o.obj_part AND par_org = o.obj_part_org ), r5events, r5eventequipreplacement e
  WHERE  n.obj_code     = eer_newobject
  AND    n.obj_org      = eer_newobject_org
  AND    o.obj_code     = eer_object
  AND    o.obj_org      = eer_object_org
  AND    evt_code       = eer_event   
  AND    eer_event      = @event
  AND    eer_object     = @obj
  AND    eer_object_org = @objorg
  AND    usr_code       = @eamuser

  IF @eerevent IS NULL
    /* Not a valid replacement record found, exit. */
    RETURN

  IF @eerprocessed = N'+'
    /* Current record has already been processed, exit. */
    RETURN

  IF     @eercorereturn  = N'-' 
     AND @eerwithdraw    = N'-' 
     AND @eerstorereturn = N'-'
    BEGIN 
      /* One of the actions needs to be selected.  If not, set error flag and exit.*/
      SET @chk = N'1'
      RETURN
    END

  /* Check whether parent and child equipment are still related. */
  SELECT @cnt = COUNT(*)
  FROM   dbo.o7getequipchildparent( @eerobject, @eerobjectorg )
  WHERE  parent    = @evtobject
  AND    parentorg = @evtobjectorg
  IF @cnt = 0
    BEGIN
      /* Parent and child are no longer related, set error flag and exit.*/
      SET @chk = N'2'
      RETURN
    END

  /* Check whether the new child has the correct status. */
  IF @objrstatus NOT IN ( N'B', N'C' ) OR @objparent IS NOT NULL OR @objposition IS NOT NULL 
    BEGIN
      /* New child equipment is not in store, or has parents, set error flag and exit.*/
      SET @chk = N'3'
      RETURN
    END

  /* Check store security. */
  IF @storesec <> 'OFF'
    BEGIN
      SELECT @cnt = COUNT(*)
      FROM   r5storesecurity
      WHERE  ssc_group = @eamgroup
      AND    ssc_store = @eerstore
      AND    ISNULL( ssc_issuereturn, N'-'


