CREATE PROCEDURE O7WOSAFETYPERMIT
  @destrentity   NVARCHAR( 4 ),
  @destcode      NVARCHAR( 30 ),
  @action        NVARCHAR( 10 ),
  @what          NVARCHAR( 10 ),
  @oldobj        NVARCHAR( 30 ),
  @oldobjorg     NVARCHAR( 15 ),
  @oldloc        NVARCHAR( 30 ),
  @oldlocorg     NVARCHAR( 15 ),
  @oldstwo       NVARCHAR( 20 ),
  @matlist       NVARCHAR( 20 ),
  @matlistrev    NUMERIC( 4 )
AS
BEGIN
  DECLARE @dosafety                      NVARCHAR( 5 )
  DECLARE @dopermit                      NVARCHAR( 5 )
  DECLARE @objchanged                    NVARCHAR( 5 )
  DECLARE @locchanged                    NVARCHAR( 5 )
  DECLARE @stwochanged                   NVARCHAR( 5 )
  DECLARE @chk                           NVARCHAR( 4 )
  DECLARE @ppm                           NVARCHAR( 20 )
  DECLARE @ppmrev                        NUMERIC( 8 )
  DECLARE @ppmorg                        NVARCHAR( 15 )
  DECLARE @ppmreviewrequired             DATETIME
  DECLARE @ppmpermitreviewrequired       DATETIME
  DECLARE @stwo                          NVARCHAR( 20 )
  DECLARE @stwoorg                       NVARCHAR( 15 )
  DECLARE @stworeviewrequired            DATETIME
  DECLARE @stwopermitreviewrequired      DATETIME
  DECLARE @obj                           NVARCHAR( 30 )
  DECLARE @objorg                        NVARCHAR( 15 )
  DECLARE @objrentity                    NVARCHAR( 4 )
  DECLARE @objreviewrequired             DATETIME
  DECLARE @objpermitreviewrequired       DATETIME
  DECLARE @routeparent                   NVARCHAR( 30 )
  DECLARE @wotype                        NVARCHAR( 1 )
  DECLARE @class                         NVARCHAR( 8 )
  DECLARE @classorg                      NVARCHAR( 15 )
  DECLARE @cat                           NVARCHAR( 30 )
  DECLARE @catorg                        NVARCHAR( 15 )
  DECLARE @catreviewrequired             DATETIME
  DECLARE @catpermitreviewrequired       DATETIME
  DECLARE @par                           NVARCHAR( 30 )
  DECLARE @parorg                        NVARCHAR( 15 )
  DECLARE @parreviewrequired             DATETIME
  DECLARE @parpermitreviewrequired       DATETIME
  DECLARE @objloc                        NVARCHAR( 30 )
  DECLARE @objlocorg                     NVARCHAR( 15 )
  DECLARE @objlocreviewrequired          DATETIME
  DECLARE @objlocpermitreviewrequired    DATETIME
  DECLARE @objlocpar                     NVARCHAR( 30 )
  DECLARE @objlocparorg                  NVARCHAR( 15 )
  DECLARE @objlocparreviewrequired       DATETIME
  DECLARE @objlocparpermitreviewrequired DATETIME
  DECLARE @loc                           NVARCHAR( 30 )
  DECLARE @locorg                        NVARCHAR( 15 )
  DECLARE @locreviewrequired             DATETIME
  DECLARE @locpermitreviewrequired       DATETIME
  DECLARE @locpar                        NVARCHAR( 30 )
  DECLARE @locparorg                     NVARCHAR( 15 )
  DECLARE @locparreviewrequired          DATETIME
  DECLARE @locparpermitreviewrequired    DATETIME
  DECLARE @r5user                        NVARCHAR( 255 )
  DECLARE @permclea                      NVARCHAR( 100 )  
  DECLARE @ptwauto                       NVARCHAR( 100 )
  DECLARE @ptwmec                        NVARCHAR( 100 )
  DECLARE @ptwlimit                      NVARCHAR( 100 )
  DECLARE @oldcat                        NVARCHAR( 30 )
  DECLARE @oldobjloc                     NVARCHAR( 30 )
  DECLARE @oldobjlocorg                  NVARCHAR( 15 )
  DECLARE @wo                            NVARCHAR( 30 )
  DECLARE @woorg                         NVARCHAR( 15 )
  DECLARE @return                        INT
  DECLARE @pk                            NVARCHAR( 100 )
  DECLARE @proccode                      NVARCHAR( 100 )
  DECLARE @part                          NVARCHAR( 30 )
  DECLARE @partorg                       NVARCHAR( 15 )
  DECLARE @partreviewrequired            DATETIME
  DECLARE @copyequip                     NVARCHAR( 1 )
  DECLARE @copyloc                       NVARCHAR( 1 )
  DECLARE @destorg                       NVARCHAR( 15 )
  DECLARE @pevcode                       NVARCHAR( 50 )
  DECLARE @ptwevent                      NVARCHAR( 30 )
  DECLARE @openptws                      NUMERIC
  DECLARE @initpermit                    NVARCHAR( 500 )
  DECLARE @initsafety                    NVARCHAR( 500 )

  SET @dosafety    = N'FALSE'
  SET @dopermit    = N'FALSE'
  SET @objchanged  = N'FALSE'
  SET @locchanged  = N'FALSE'
  SET @stwochanged = N'FALSE'
  SET @copyequip   = N'-'
  SET @copyloc     = N'-'

  IF @what LIKE N'COPY%'
    BEGIN
       /* COPYxx is used to copy/replace a PTW. */
      SET @copyequip = SUBSTRING( @what, 5, 1 );
      SET @copyloc   = SUBSTRING( @what, 6, 1 );
      SET @dosafety  = N'TRUE'
    END
  ELSE
    BEGIN
      IF CHARINDEX( N'S', @what ) > 0
        SET @dosafety = N'TRUE'
      IF CHARINDEX( N'P', @what ) > 0 AND @destrentity = N'EVNT'
        SET @dopermit = N'TRUE'
    END

  IF @destrentity = N'EVNT'
    BEGIN
      IF @action = 'DELETE'
        BEGIN
          /* Delete permit and safety records. */
          DELETE FROM r5permevents
          WHERE  pev_event = @destcode
          DELETE FROM r5worksafety
          WHERE  ksf_rentity = N'EVNT'
          AND    ksf_code    = @destcode
        END
      ELSE 
        /* Retrieve WO data. */
        SELECT @destorg                    = evt_org, 
               @ppm                        = evt_ppm, 
               @ppmrev                     = evt_ppmrev, 
               @ppmorg                     = ppm_org, 
               @ppmreviewrequired          = ppm_safetyreviewrequired, 
               @ppmpermitreviewrequired    = ppm_permitreviewrequired, 
               @stwo                       = evt_standwork, 
               @stwoorg                    = stw_org, 
               @stworeviewrequired         = stw_safetyreviewrequired,
               @stwopermitreviewrequired   = stw_permitreviewrequired,
               @obj                        = evt_object, 
               @objorg                     = evt_object_org, 
               @objrentity                 = CASE evt_obrtype WHEN N'L' THEN N'LOC' ELSE N'OBJ' END, 
               @objreviewrequired          = o1.obj_safetyreviewrequired,
               @objpermitreviewrequired    = o1.obj_permitreviewrequired,
               @r5user                     = COALESCE( evt_updatedby, evt_createdby, N'R5' ),  
               @routeparent                = evt_routeparent,
               @wotype                     = CASE evt_multiequip WHEN  N'+' THEN N'H' ELSE CASE WHEN evt_routeparent IS NULL THEN N'N' ELSE N'C' END END,
               @class                      = o1.obj_class,
               @classorg                   = o1.obj_class_org,
               @cat                        = o1.obj_category, 
               @catorg                     = N'*', 
               @catreviewrequired          = o2.obj_safetyreviewrequired,
               @catpermitreviewrequired    = o2.obj_permitreviewrequired,
               @objloc                     = o1.obj_location, 
               @objlocorg                  = o1.obj_location_org, 
               @objlocreviewrequired       = o3.obj_safetyreviewrequired,
               @objlocpermitreviewrequired = o3.obj_permitreviewrequired,
               @loc                        = evt_location, 
               @locorg                     = evt_location_org, 
               @locreviewrequired          = o4.obj_safetyreviewrequired,
               @locpermitreviewrequired    = o4.obj_permitreviewrequired,
               @permclea                   = oo1.opa_desc,
               @ptwauto                    = oo2.opa_desc,
               @ptwmec                     = oo3.opa_desc,
               @ptwlimit                   = oo4.opa_desc,
               @initsafety                 = ISNULL( CAST( evt_safetyreviewed AS NVARCHAR ), '.' ) +


